#include<bits/stdc++.h>
#define int long long
using namespace std;
int a[5555],dp[5555],ans[5555];
map<int,int>m;
int n;
int mod=1e9+7;
signed main() {
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	cin>>n;
	for(int i=1;i<=n;i++){
		cin>>a[i];
	}
	int k=0;
	for(int i=n;i>=1;i--){
		dp[i]=1;
		ans[i]=1;
		for(int j=i+1;j<=n;j++){
			if(a[i]<a[j]){
				if(dp[i]<dp[j]+1){
					dp[i]=dp[j]+1;
					ans[i]=ans[j];
				}else if(dp[i]==dp[j]+1){
					ans[i]+=ans[j];
					ans[i]%=mod;
				}
			}
		}
		k=max(k,dp[i]);
	}
	int sum=0;
	for(int i=1;i<=n;i++){
		if(dp[i]==k){
			sum+=ans[i];
		}
	}
	cout<<sum;
	return 0;
}
